function settings() {
  const s = data.settings;
  return heading("Settings","Configure discovery, cloud preparation and browser connections.")+'<div class="box"><h2>Gmail browser connection</h2><p>Sign in once in an isolated Google browser window. The agent can then prepare unsent email drafts with your CV. Each send requires your explicit approval.</p><button id="connect-gmail">'+(s.gmail_browser_connected?"Reconnect Gmail":"Connect Gmail")+'</button></div><div class="box"><form id="settings-form">'+
    '<h2>Cloud AI</h2><p id="cloud-status">Uses the saved ChatGPT login.</p><button type="button" id="check-cloud">Check ChatGPT connection</button><p>Uses your existing Codex login with ChatGPT. Plan limits apply. Search itself never runs a model. Preparing an application sends the selected post, share-approved facts and master CV text to ChatGPT.</p><label>Cloud model<input name="cloud_model" value="'+esc(s.cloud_model||'gpt-6.1-sol')+'"></label><h2>Discovery & extraction</h2><label>Operating schedule<select name="discovery_schedule_mode"><option value="manual" '+(!s.discovery_schedule_mode || s.discovery_schedule_mode==="manual"?"selected":"")+'>Manual only · Run search</option><option value="always" '+(s.discovery_schedule_mode==="always"?"selected":"")+'>Automatic intervals while app is running</option><option value="window" '+(s.discovery_schedule_mode==="window"?"selected":"")+'>Only in working window</option></select></label>'+
    '<label>Automatic check interval (minutes; ignored in manual mode)<input type="number" name="discovery_interval_minutes" min="5" max="1440" value="'+esc(s.discovery_interval_minutes || 30)+'" required></label>'+
    '<label>Maximum new model extractions per run<input name="extraction_batch_limit" type="number" min="1" max="20" value="'+esc(s.extraction_batch_limit || 5)+'"></label>'+
    '<label>Extraction provider<select name="extraction_provider">'+[["codex","ChatGPT via Codex · cloud"],["regex","Fast rules only"],["ollama","Ollama · optional local inference"],["local_chat","Local chat server · optional"]].map(([v,t])=>'<option value="'+v+'" '+(s.extraction_provider===v?'selected':'')+'>'+t+'</option>').join("")+'</select></label>'+
    '<label>Local model (only used with local providers)<input name="extraction_model" value="'+esc(s.extraction_model || "qwen3:4b")+'" required></label>'+
    '<label>Local provider endpoint<input name="extraction_endpoint" value="'+esc(s.extraction_endpoint || "http://127.0.0.1:11434")+'" required></label>'+
    '<label>Minimum field confidence<input type="number" name="extraction_threshold" min="0.5" max="1" step="0.05" value="'+esc(s.extraction_threshold || .8)+'"></label>'+
    '<p class="muted">Search saves posts quickly without model inference. Cloud AI is used for explicit application preparation and post extraction; local providers run only if you select them. Manual mode never starts discovery at login or on a timer. Ollama unloads the extraction model after each request.</p>'+
    '<h2>Working window · Hong Kong</h2><div class="row">'+["Mon","Tue","Wed","Thu","Fri","Sat","Sun"].map((d,n)=>'<label><input type="checkbox" name="days" value="'+n+'" '+(s.days.includes(n)?"checked":"")+'> '+d+'</label>').join("")+'</div>'+
    '<div class="row"><label>Starts <input name="start" type="time" value="'+esc(s.start)+'" required></label><label>Ends <input name="end" type="time" value="'+esc(s.end)+'" required></label></div>'+
    '<label><input name="ac_only" type="checkbox" '+(s.ac_only?"checked":"")+'> Run on AC power only</label><h2>Official employer boards</h2><div class="row">'+
    Object.entries(data.sources).filter(([k])=>!k.startsWith("telegram:")).map(([k,v])=>'<label><input type="checkbox" name="sources" value="'+esc(k)+'" '+(s.enabled_sources.includes(k)?"checked":"")+'> '+esc(v)+'</label>').join("")+
    '</div><h2>Public Telegram channels</h2><label>Channel usernames, separated by spaces<textarea name="telegram_channels" placeholder="channel_one channel_two">'+esc((s.telegram_channels || []).join(" "))+'</textarea></label>'+
    '<label>Sources allowed for form prefill<textarea name="source_allowlist" placeholder="telegram:channel_one">'+esc((s.source_allowlist || []).join(" "))+'</textarea></label><p class="muted">Adding a channel enables discovery. The allow-list permits verified, share-approved facts to be entered in its linked Google Forms when you click Prefill.</p><h2>Ranking weights</h2><div class="form-grid">'+Object.entries(s.weights).map(([k,v])=>'<label>'+esc(label(k))+' <input type="number" min="0" max="100" required name="'+esc(k)+'" value="'+v+'"></label>').join("")+
    '</div><h2>Legacy local drafting (unused by cloud preparation)</h2><label>Ollama model (optional)<input name="ollama_model" maxlength="100" value="'+esc(s.ollama_model)+'" placeholder="Installed local model"></label><label>Essay style and instructions<textarea name="essay_style" maxlength="2000">'+esc(s.essay_style)+'</textarea></label><button class="primary">Save settings</button></form></div>'+telegramSettings();
}
async function watchReview(id) {
  try {
    const response = await fetch("/api/reviews");
    if (!response.ok) throw Error("Could not load form review");
    const {reviews} = await response.json();
    const review = reviews.find(r=>r.id===id);
    const target = $("#prefill-result");
    if (!target) return;
    if (!review || review.status==="Running") {
      setTimeout(()=>watchReview(id),2000);
      return;
    }
    target.innerHTML = review.error ? empty(review.error) :
      '<h3>Form prepared · review required</h3><p>'+esc(review.title)+'</p><button data-close-review="'+review.id+'">Close prepared browser</button>'+
      '<ul>'+review.fields.map(f=>'<li>'+esc(f.label)+' · '+(f.filled?'Filled from verified fact':esc(f.attention))+'</li>').join("")+'</ul>'+
      '<p>'+link(review.url,"Open original form to continue manually")+'</p><p class="muted">The filled browser stays open for up to 10 minutes with submission blocked. This screenshot is saved locally. The original link opens a fresh form.</p>'+
      '<img alt="Google Form prefill review" class="review-image" src="/api/review/'+review.id+'">';
  } catch (error) { flash(error.message); }
}

async function loadFormReviews() {
  try {
    const response=await fetch("/api/reviews");
    if (!response.ok) return;
    const {reviews}=await response.json();
    const target=$("#form-reviews");
    if (!target || !reviews.length) return;
    target.innerHTML='<div class="section"><h2>Prepared Google Forms</h2></div><div class="stack">'+reviews.map(r=>{
      const item=data.items.find(i=>i.id===r.opportunity);
      return item ? '<div class="box"><strong>'+esc(displayTitle(item.title))+'</strong><p>'+esc(r.status)+'</p><button data-form-review="'+r.id+'" data-opportunity="'+esc(r.opportunity)+'">Open form review</button></div>' : "";
    }).join("")+'</div>';
  } catch {}
}
document.addEventListener("click",async event=>{
  const evidence=event.target.closest("[data-evidence]");
  if(evidence){evidenceTerm=evidence.dataset.evidence;highlightPost();return;}
  const button=event.target.closest("button");
  if(!button||button.disabled)return;
  try{
    if(button.id==="connect-gmail"){const result=await post("browser/gmail-connect",{});await navigate("Review Center");await load();render();watchBrowser(result.job);flash("Sign in once in the opened Google browser window.");}
    else if(button.dataset.browserStart)await startBrowser(button.dataset.browserStart);
    else if(button.dataset.browserAllow){await post("browser/allow",{id:button.dataset.browserAllow});await startBrowser(button.dataset.browserAllow);}
    else if(button.dataset.browserControl){const job=browserJobs.find(j=>j.id===button.dataset.job);button.disabled=true;try{await post("browser/control",{id:job.id,action:button.dataset.browserControl,approval_token:job.approval_token});flash(button.dataset.browserControl==="approve"?"Submitting exactly the reviewed application…":"Browser action requested");}finally{button.disabled=false;}}
    else if(button.id==="check-cloud"){const status=await fetch("/api/ai/status").then(r=>r.json());$("#cloud-status").textContent=status.message;flash(status.message);}
    else if(button.dataset.prepare)await startPreparation(button.dataset.prepare);
    else if(button.dataset.cancelTask){await post("tasks/cancel",{id:button.dataset.cancelTask});flash("Cancelling cloud preparation…");}
    else if(button.hasAttribute("data-refresh-listings"))await mutate("agent",{action:"run"},"Fast search started. Results appear as sources finish.");
    else if(button.dataset.nav)await navigate(button.dataset.nav);
    else if(button.dataset.detail)showDetail(button.dataset.detail);
    else if(button.dataset.laneTarget){
      const lane=document.querySelector('[data-stage="'+button.dataset.laneTarget+'"]');
      lane.parentElement.scrollTo({left:lane.offsetLeft-lane.parentElement.offsetLeft,behavior:"smooth"});
    }
    else if(button.dataset.edit)showApplication(button.dataset.edit);
    else if(button.dataset.step)step(Number(button.dataset.step));
    else if(button.dataset.jump){triageId=button.dataset.jump;renderTriage();}
    else if(button.dataset.triageChoice)await triageChoice(button.dataset.triageChoice);
    else if(button.dataset.formReview){showDetail(button.dataset.opportunity);watchReview(button.dataset.formReview);}
    else if(button.dataset.closeReview)await mutate("review-close",{id:button.dataset.closeReview},"Review browser closed");
    else if(button.id==="prefill-form"){
      button.disabled=true;
      try{const result=await post("prefill",{id:selected.id});$("#prefill-result").textContent="Preparing your form…";watchReview(result.review);}
      finally{button.disabled=false;}
    }
    else if(button.id==="inspect-form"){
      button.disabled=true;
      try{
        const result=await post("form",{id:selected.id});
        $("#portal-questions").innerHTML=result.questions.length?'<ul>'+result.questions.map(q=>'<li>'+esc(q.label||q.group)+(q.required?" · Required":"")+'</li>').join("")+'</ul>':empty("No questions available. Check the original application.");
      }finally{button.disabled=false;}
    }
    else if(button.dataset.action)await mutate("application",{id:button.closest("[data-app]").dataset.app,action:button.dataset.action},"Application updated");
    else if(["run","pause","stop"].includes(button.id))await mutate("agent",{action:button.id});
    else if(button.id==="cancel-confirm")$("#confirm").close();
  }catch(error){flash(error.message);}
});
window.addEventListener("hashchange",()=>{const target=Object.keys(routes).find(k=>routes[k]===location.hash.slice(1));if(target && target!==page)navigate(target);});
document.addEventListener("keydown",async event=>{
  if(event.ctrlKey||event.metaKey||event.altKey||event.repeat||$("#detail").open||$("#confirm").open||
    event.target.closest("input,textarea,select,[contenteditable=true]")||!["Today","Inbox"].includes(page))return;
  const key=event.key.toLowerCase();
  if(!["a","r","s","j","k"].includes(key))return;
  event.preventDefault();
  try{if(key==="j"||key==="k")step(key==="j"?1:-1);else await triageChoice({a:"auto",r:"review",s:"skip"}[key]);}catch(error){flash(error.message);}
});
document.addEventListener("input",event=>{
  const keys={search:"q",group:"group",pay:"pay",hidden:"hidden"};
  if(keys[event.target.id]){filter[keys[event.target.id]]=event.target.type==="checkbox"?event.target.checked:event.target.value;triageId=null;renderTriage();}
});
document.addEventListener("change",async event=>{
  if(!event.target.dataset.move||!event.target.value)return;
  try{await moveApplication(event.target.dataset.move,event.target.value);}catch(error){flash(error.message);}
  finally{event.target.value="";}
});
document.addEventListener("dragstart",event=>{
  const item=event.target.closest("[data-pipeline]");
  if(!item)return;
  dragging=item.dataset.pipeline;event.dataTransfer.setData("text/plain",dragging);event.dataTransfer.effectAllowed="move";
});
document.addEventListener("dragover",event=>{
  const lane=event.target.closest("[data-stage]");
  if(!lane||!dragging)return;
  event.preventDefault();event.dataTransfer.dropEffect="move";lane.classList.add("drop-target");
});
document.addEventListener("dragleave",event=>{
  const lane=event.target.closest("[data-stage]");
  if(lane&&!lane.contains(event.relatedTarget))lane.classList.remove("drop-target");
});
document.addEventListener("dragend",()=>{dragging=null;document.querySelectorAll(".drop-target").forEach(el=>el.classList.remove("drop-target"));});
document.addEventListener("drop",async event=>{
  const lane=event.target.closest("[data-stage]");
  if(!lane||!dragging)return;event.preventDefault();
  const id=dragging;dragging=null;lane.classList.remove("drop-target");
  try{await moveApplication(id,lane.dataset.stage);}catch(error){flash(error.message);}
});
document.addEventListener("submit",async event=>{
  const form=event.target;if(form.method==="dialog")return;event.preventDefault();
  const values=new FormData(form),button=form.querySelector('button:not([type="button"])');if(button)button.disabled=true;
  try{
    if(form.id==="add-source-form"){
      const result=await post("sources/add",{channel:values.get("channel")});
      await load();render();flash("@"+result.channel+" saved · "+(result.status==="queued" && data.settings.discovery_schedule_mode==="manual"?"click Run search to fetch":result.status));
    }
    else if(form.id==="paste-post-form"){
      flash("Extracting post with your local provider…");
      const result=await post("inbox/paste",{content:values.get("content"),source_link:values.get("source_link")});
      filter.q="";triageId=result.id;await load();render();showDetail(result.id);flash("Post extracted and saved");
    }
    else if(form.id==="telegram-settings-form"){
      await post("telegram",{token:values.get("token"),chat_id:values.get("chat_id"),enabled:values.has("enabled")});
      await load();render();flash("Telegram preferences saved");
    }
    else if(form.id==="confirm-form"){
      await mutate("application",{id:pendingSubmission,action:"submitted",evidence:values.get("evidence")},"Submission recorded");
      $("#confirm").close();
    }
    else if(form.id==="choice-form"){
      await mutate("choice",{id:selected.id,choice:values.get("choice")},"Preference saved");
      selected=data.items.find(i=>i.id===selected.id);
    }
    else if(form.id==="draft-form"){
      await startPreparation(selected.id,values.get("prompt"),Number(values.get("words")));
    }
    else if(form.dataset.emailEdit){await post("application/email",{id:form.dataset.emailEdit,subject:values.get("subject"),body:values.get("body")});await load();showApplication(form.dataset.emailEdit);flash("Email draft saved");}
    else if(form.dataset.action)await mutate("application",{...Object.fromEntries(values),id:form.closest("[data-app]").dataset.app,action:form.dataset.action},"Application updated");
    else if(form.dataset.fact)await mutate("fact",{key:form.dataset.fact,value:values.get("value"),source:values.get("source"),verified:values.has("verified"),share:values.has("share")},"Profile saved");
    else if(form.id==="settings-form")await mutate("settings",{...Object.fromEntries(values),ac_only:values.has("ac_only"),discovery_interval_minutes:Number(values.get("discovery_interval_minutes")),extraction_threshold:Number(values.get("extraction_threshold")),days:values.getAll("days").map(Number),enabled_sources:values.getAll("sources"),weights:Object.fromEntries(Object.keys(data.settings.weights).map(k=>[k,Number(values.get(k))]))},"Settings saved");
    else if(form.id==="document-form"){
      const file=values.get("file");if(!file.size||file.size>10000000)throw Error("Choose a document up to 10 MB");
      const encoded=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(",")[1]);reader.onerror=reject;reader.readAsDataURL(file);});
      await mutate("document",{name:file.name,content:encoded},"Document imported");
    }
  }catch(error){flash(error.message);}
  finally{if(button)button.disabled=false;}
});
