setInterval(async()=>{
  if(document.hidden)return;
  try{
    const response=await fetch("/api/heartbeat");if(!response.ok)return;
    const {agent,agent_progress,revision,last_checked}=await response.json();renderAgent(agent,agent_progress);renderLastChecked(last_checked);
    if(!["Profile","Settings"].includes(page)&&!$("#detail").open&&!document.activeElement.closest("input,textarea,select")&&data?.revision!==revision){await load();render();}
  }catch{}
},5000);

function renderLastChecked(value){
  let indicator=$("#last-checked");
  if(!indicator){indicator=document.createElement("span");indicator.id="last-checked";$("#agent-status").insertAdjacentElement("afterend",indicator);}
  if(!value){indicator.textContent="Not checked yet";return;}
  const minutes=Math.max(0,Math.floor((Date.now()-Date.parse(value))/60000));
  indicator.textContent=minutes<1?"Checked just now":minutes<60?"Checked "+minutes+"m ago":minutes<1440?"Checked "+Math.floor(minutes/60)+"h ago":"Checked "+Math.floor(minutes/1440)+"d ago";
  indicator.title=new Date(value).toLocaleString("en-HK",{timeZone:"Asia/Hong_Kong"});
}
