// Font bytes travel in this same-origin asset. No extra font route or CSP exception is needed.
const localFonts = [{"family": "Bricolage Grotesque", "weight": "700", "bytes": ""}, {"family": "Instrument Sans", "weight": "400", "bytes": ""}];
window.fontsReady = Promise.all(localFonts.map(async ({family, weight, bytes}) => {
  const font = new FontFace(family, Uint8Array.from(atob(bytes), c => c.charCodeAt(0)), {weight});
  await font.load();
  document.fonts.add(font);
})).catch(error => console.warn("Local font fallback", error));
